# type() is the default metaclass
print(type(int))      # <class 'type'>
print(type(str))      # <class 'type'>

class Foo:
    pass
print(type(Foo))      # <class 'type'>

# Custom metaclass: enforce method contracts at class creation
class InterfaceMeta(type):
    REQUIRED_METHODS = ('process', 'validate')

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if bases:  # skip the base class itself
            for method in mcs.REQUIRED_METHODS:
                if not callable(getattr(cls, method, None)):
                    raise TypeError(
                        f"{name} must implement {method}()"
                    )
        return cls

class Handler(metaclass=InterfaceMeta):
    def process(self): ...
    def validate(self): ...

# class BrokenHandler(metaclass=InterfaceMeta): pass  # TypeError at class definition

# Auto-registry pattern
class PluginMeta(type):
    registry = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if bases:  # don't register the base class
            mcs.registry[name] = cls
        return cls

class Plugin(metaclass=PluginMeta):
    pass

class CSVPlugin(Plugin):
    pass

class JSONPlugin(Plugin):
    pass

print(PluginMeta.registry)  # {'CSVPlugin': <class 'CSVPlugin'>, 'JSONPlugin': ...}

# Modern alternative: __init_subclass__ (no metaclass needed)
class PluginBase:
    _registry = {}

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        PluginBase._registry[cls.__name__] = cls

class XMLPlugin(PluginBase):
    pass

print(PluginBase._registry)  # {'XMLPlugin': <class 'XMLPlugin'>}
